        if (pts != UINT64_MAX) {
            uref_clock_set_pts(uref, pts);
        }
    }

    /* compute next pts based on current frame duration */
    if (pts != UINT64_MAX && uref_clock_get_duration(uref, &duration)) {
        upipe_avcdec->next_pts = pts + duration;
